import type { CourseUnitTestConfig, UnitDef, UnitPoolQuestion } from '@/lib/unit-tests/engine'

/**
 * Algebra 2 unit tests.
 *
 * The Algebra 2 competitive bank held only ~20 questions — far too few for four
 * distinct 12-question variants across six units — so this pool is written for
 * these unit tests. Units follow a standard Algebra 2 sequence.
 */
const q = (domain: string, topicSlug: string, question: string, options: string[], explanation: string): UnitPoolQuestion =>
  ({ domain, topicSlug, question, options, correctAnswer: 0, explanation })

const eq = (t: string, a: string, o: string[], e: string) => q('equations-inequalities', t, a, o, e)
const quad = (t: string, a: string, o: string[], e: string) => q('quadratics', t, a, o, e)
const poly = (t: string, a: string, o: string[], e: string) => q('polynomials-rational', t, a, o, e)
const exp = (t: string, a: string, o: string[], e: string) => q('exponential-log', t, a, o, e)
const trig = (t: string, a: string, o: string[], e: string) => q('trigonometry-alg2', t, a, o, e)
const seq = (t: string, a: string, o: string[], e: string) => q('sequences-probability', t, a, o, e)

